inline const char* key(qt::Text role){
 switch(role){
 case qt::Text::Delay:return "LabelDelay";case qt::Text::Current:return "LabelCurrentOffset";case qt::Text::Recommended:return "LabelTargetOffset";case qt::Text::Residual:return "LabelCurrentResidual";case qt::Text::Confidence:return "LabelConfidence";case qt::Text::State:return "LabelMeasurement";case qt::Text::Milliseconds:return "FormatMilliseconds";
 case qt::Text::Unknown:return "ConfidenceUnknown";case qt::Text::Stable:return "ConfidenceStable";case qt::Text::Invalid:return "StatusInvalidEstimate";case qt::Text::Silent:return "StatusSilent";case qt::Text::Muted:return "StatusMuted";case qt::Text::Low:return "ConfidenceLow";case qt::Text::Read:return "BtnRefreshOffset";case qt::Text::Apply:return "BtnRecommend";case qt::Text::Reset:return "BtnResetOffset";case qt::Text::Settings:return "BtnSettings";case qt::Text::Undo:return "BtnUndo";case qt::Text::Manual:return "BtnApplyOffset";case qt::Text::Minus5:return "BtnMinus5";case qt::Text::Minus1:return "BtnMinus1";case qt::Text::Plus1:return "BtnPlus1";case qt::Text::Plus5:return "BtnPlus5";case qt::Text::Waiting:return "StatusMeasuring";case qt::Text::NoBaseline:return "StatusNoBaseline";case qt::Text::Protected:return "StatusProtected";case qt::Text::Expired:return "StatusStale";case qt::Text::Unconnected:return "StatusManualUnavailable";
 }return "ConfidenceUnknown";
}
